<?php
declare(strict_types=1);
function mbsh_campaign_message(string $wave, bool $proof=false):array {
 $ticket='<p style="margin:26px 0;text-align:center"><a href="https://mbsh96reunion.com/tickets.html#ticket-order" style="display:inline-block;background:#c8102e;color:#fff;text-decoration:none;font-weight:bold;padding:15px 20px;border-radius:8px">GET MY $30 MIXER TICKET</a></p>';
 $event='<p style="padding:16px;border:1px solid #735525;border-radius:8px;color:#e5bd67"><strong>Saturday, November 7 · 7–10 PM</strong><br>Twisted Tonic inside The Lincoln Eatery<br>723 Lincoln Lane North, Miami Beach<br><strong>$30 per person · No additional checkout fee</strong><br><span style="font-size:14px;color:#cdbfae">Food is on your own. No separate RSVP is needed.</span></p>';
 $greeting='<p style="margin-top:0">Hey, Hi-Tide!</p>';
 $waves=[
 'friday'=>['subject'=>'Unlock the Night, Class of ’96','title'=>'Unlock the Night, Class of ’96','date'=>'Friday, October 23 · 6 PM Eastern','preheader'=>'Thirty years of stories. One Miami Beach night. Your $30 mixer ticket starts here.','harry'=>'act-1/ticket-premiere.png','body'=>$greeting.'<p>Remember the faces you could spot across the courtyard? The conversations that picked up right where they left off? <strong style="color:#f3c76d">Let’s have another one of those nights.</strong></p><p>Our Class of ’96 is coming home to Miami Beach. Join us at Twisted Tonic for the reunion mixer—old friends, new stories, and a room full of Hi-Tides.</p>'.$event.$ticket.'<p><strong>Get your reunion account ready, too.</strong> Use the same email address for your ticket and private account so you can open your paid ticket in My Reunion. You can buy your ticket before creating an account.</p><p><a href="https://mbsh96reunion.com/portal/register" style="color:#f3c76d">Create my reunion account</a> · <a href="https://mbsh96reunion.com/portal/login" style="color:#f3c76d">Already registered? Sign in</a></p><p>We’re planning trivia, points, and photo moments for mixer night. Get ready to join in when the host opens the activities—and bring a favorite story from ’96.</p><p>Know a classmate who should be in that room? Send them <a href="https://mbsh96reunion.com" style="color:#f3c76d">mbsh96reunion.com</a>.</p>'],
 'sunday'=>['subject'=>'Think You Remember ’96?','title'=>'Think You Remember ’96?','date'=>'Sunday, October 25 · 11 AM Eastern','preheader'=>'A little ’96 trivia to warm you up for our November 7 mixer.','harry'=>'act-1/trailer-curtain-host.png','body'=>$greeting.'<p>Before you say “I remember everything,” try this one:</p><div style="padding:20px;background:#260d13;border-left:3px solid #e5bd67"><p style="margin:0 0 12px;font-family:Georgia,serif;font-size:22px;color:#fff8e9">Which film won Best Picture at the 1996 Academy Awards?</p><p style="margin:0;color:#e5bd67">A. Apollo 13<br>B. Braveheart<br>C. Babe</p></div><p>Got your answer? Keep it in mind. That’s the kind of throwback energy we’re bringing to the reunion.</p><p><strong>We’re planning trivia and points for mixer night, with the host bringing everyone together for the results.</strong> The game isn’t open yet; this is your warm-up. No studying required—just a little Class of ’96 confidence.</p>'.$event.$ticket.'<p>Your private reunion account will keep your paid ticket within reach. <a href="https://mbsh96reunion.com/portal/register" style="color:#f3c76d">Create your account</a> or <a href="https://mbsh96reunion.com/portal/login" style="color:#f3c76d">sign in</a> with the same email you use to buy your ticket.</p><p>The best part won’t be getting every answer right. It’ll be hearing the stories that come after.</p>'],
 'monday'=>['subject'=>'Your Story Belongs Here','title'=>'Your Story Belongs Here','date'=>'Monday, October 26 · 10 AM Eastern','preheader'=>'Find that throwback photo. Bring that unforgettable story. Come make the next memory.','harry'=>'act-1/registration-welcome.png','body'=>$greeting.'<p>Somewhere there’s a photo that needs a second look. A hallway story that still gets a laugh. A friend you’ve been meaning to catch up with.</p><p><strong style="color:#f3c76d">Your piece of ’96 belongs in the room.</strong></p><p>Start looking for a favorite throwback photo or memory. We’re planning ways to share those stories—and photos from mixer night—through the reunion experience. Submissions will be reviewed by the committee before anything appears publicly.</p><p>Have a memory ready or need help sharing it? Reply to this email and the committee can help. Please share only photos and stories you have permission to share.</p>'.$event.'<p>If you’re still planning to join us, your mixer ticket is <strong>$30</strong>. Come catch up and help us make the next chapter.</p>'.$ticket.'<p>Can’t make it? You can still reply with a memory or ask the committee how to contribute to the reunion story.</p>']
 ];
 if(!isset($waves[$wave]))throw new InvalidArgumentException('Unknown wave');$w=$waves[$wave];
 $body=$w['body'].'<p>See you by the tide,<br><strong style="color:#e5bd67">Hi-Tide Harry</strong><br><span style="font-size:13px;color:#cdbfae">Your Class of ’96 reunion host</span></p>';
 $body.='<p style="font-size:12px;color:#b8ada0">Manage optional email in your <a href="https://mbsh96reunion.com/portal/#notifications" style="color:#e5bd67">reunion account preferences</a>, or reply “unsubscribe” for committee assistance. Essential ticket and account messages are separate.</p>';
 if($proof)$body='<p style="padding:12px;background:#f3c76d;color:#19110a;font-size:13px"><strong>OWNER PROOF · '.$w['date'].'</strong><br>This is the nonbuyer campaign version, sent only to Fritz for review. It is not an attendee send.</p>'.$body;
 $html=fam_reunion_email_layout(['title'=>$w['title'],'preheader'=>$w['preheader'],'eyebrow'=>'CLASS OF ’96 · CALLING THE HI-TIDES HOME','body'=>$body,'harry'=>$w['harry']]);
 $ad='<table role="presentation" width="100%" style="border-top:1px solid #4a3517"><tr><td style="padding:20px 0 4px;text-align:center"><p style="margin:0 0 14px;color:#fff8e9;font-size:16px;font-weight:bold">Need a website for your business?<br><span style="font-weight:normal;font-size:14px;color:#cdbfae">See what FAMtastic Designs can create.</span></p><a href="https://famtasticdesigns.com/connect/commercial.mp4" style="display:block"><img src="https://famtasticdesigns.com/connect/commercial-poster.jpg" width="400" alt="Watch the FAMtastic Designs commercial" style="display:block;width:100%;max-width:400px;height:auto;margin:0 auto;border:0;border-radius:8px"></a><p style="margin:16px 0"><a href="https://famtasticdesigns.com/connect/commercial.mp4" style="display:inline-block;padding:12px 18px;border:1px solid #e5bd67;border-radius:7px;color:#e5bd67;text-decoration:none;font-size:14px;font-weight:bold">WATCH THE COMMERCIAL</a></p><p style="margin:0"><a href="https://famtasticdesigns.com/" style="color:#e5bd67;font-size:14px;font-weight:bold">Explore FAMtastic Designs →</a></p></td></tr></table>';
 $html=preg_replace('~<table role="presentation" width="100%" style="border-top:1px solid #4a3517">.*?</table>~s',$ad,$html,1,$replaced);if($replaced!==1)throw new RuntimeException('Promo placement mismatch');
 $html=str_replace(['width="190"','width:190px'],['width="160"','width:160px'],$html);
 $plain=preg_replace_callback('~<a[^>]+href="([^"]+)"[^>]*>(.*?)</a>~s',fn($m)=>strip_tags($m[2]).' ('.html_entity_decode($m[1]).')',$body);
 $plain=preg_replace('~<(?:br\s*/?|/p|/div)[^>]*>~i',"\n",$plain);
 $plain=trim(html_entity_decode(strip_tags($plain),ENT_QUOTES,'UTF-8'))."\n\nNeed a website for your business? See what FAMtastic Designs can create.\nWatch the commercial: https://famtasticdesigns.com/connect/commercial.mp4\nExplore FAMtastic Designs: https://famtasticdesigns.com/\nCreated by FAMtastic Designs.\n";
 return ['subject'=>($proof?'[PROOF — '.$w['date'].'] ':'').$w['subject'],'html'=>$html,'text'=>$plain];
}
